const ALL_MESSAGES = Object.freeze(Object.fromEntries(SUPPORTED.map((locale) => [
  locale, Object.freeze({ ...(MESSAGES[locale] ?? {}), ...(SOCIAL_X_MESSAGES[locale] ?? {}) }),
])));

function baseLocale(value) {
  const candidate = String(value ?? "").trim().replaceAll("_", "-");
  if (!candidate || candidate.toLowerCase() === "auto") return null;
  const base = candidate.split("-")[0].toLowerCase();
  return SUPPORTED.includes(base) ? base : null;
}

export function resolveInterfaceLocale({ accountLocale = "auto", deviceLocales = [] } = {}) {
  const explicit = String(accountLocale ?? "auto").trim().toLowerCase() !== "auto";
  if (explicit) return baseLocale(accountLocale) ?? "en";
  for (const locale of Array.isArray(deviceLocales) ? deviceLocales : [deviceLocales]) {
    const supported = baseLocale(locale);
    if (supported) return supported;
  }
  return "en";
}

export function createInterfaceTranslator(locale) {
  const resolved = baseLocale(locale) ?? "en";
  return (key) => ALL_MESSAGES[resolved][key] ?? ALL_MESSAGES.en[key] ?? key;
}

export function applyInterfaceLocale(documentRef, locale) {
  const resolved = baseLocale(locale) ?? "en";
  if (documentRef?.documentElement) {
    documentRef.documentElement.lang = resolved;
    documentRef.documentElement.dir = RTL.has(resolved) ? "rtl" : "ltr";
    documentRef.documentElement.dataset.interfaceLocale = resolved;
  }
  return { locale: resolved, direction: RTL.has(resolved) ? "rtl" : "ltr" };
}

export function interfaceLocaleCoverage() {
  const requiredKeys = Object.keys(ALL_MESSAGES.en);
  return Object.fromEntries(SUPPORTED.map((locale) => [
    locale,
    requiredKeys.filter((key) => !Object.hasOwn(ALL_MESSAGES[locale], key)),
  ]));
}

export const SUPPORTED_INTERFACE_LOCALES = SUPPORTED;
